using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckMusicalParking.Editor {
public static class ParkingAuthoring {
 public const string Folder="TruckMusicalParking",Scene="Assets/TruckMusicalParking/Scenes/TruckMusicalParking.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<ParkingMatch>(Folder);m.setup.count=8;m.NormalizeSetup();m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();m.feedback.clips[2]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/NWH/Vehicle Physics 2/Sound/Horn/Horn.wav");var asphalt=SportsEventAuthoring.Mat(Folder,"Textured parking asphalt",new Color(.45f,.48f,.51f),.22f);asphalt.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NWH/Common/Textures/Ground/AsphaltAlbedo.png");asphalt.mainTextureScale=new Vector2(24,21);asphalt.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NWH/Common/Textures/Ground/AsphaltNormal.png"));asphalt.EnableKeyword("_NORMALMAP");var contact=SportsEventAuthoring.Contact(Folder,"Lot contact",.65f,.05f);SportsEventAuthoring.Box("Full 3D asphalt lot",new Vector3(0,-.25f,0),new Vector3(88,.5f,72),asphalt,contact);var edge=SportsEventAuthoring.Mat(Folder,"Circulation safety yellow",new Color(1,.79f,.19f),.1f);var white=SportsEventAuthoring.Mat(Folder,"Bay marking enamel",Color.white,.1f);for(int i=0;i<64;i++){float a=i*Mathf.PI*2/64;var paint=SportsEventAuthoring.Box("Dashed outer circulation route",new Vector3(Mathf.Sin(a)*30,.015f,Mathf.Cos(a)*23),new Vector3(.16f,.025f,1.4f),edge);paint.transform.rotation=Quaternion.LookRotation(new Vector3(Mathf.Cos(a)*30,0,-Mathf.Sin(a)*23));}
 m.bays=new ParkingBay[8];for(int i=0;i<8;i++){var root=new GameObject("Authoritative parking bay "+(i+1)).transform;root.position=new Vector3((i%4-1.5f)*11,.035f,i<4?-7:7);var b=root.gameObject.AddComponent<ParkingBay>();b.markings=new Renderer[4];for(int k=0;k<4;k++){bool side=k<2;var line=SportsEventAuthoring.Box("Painted bay boundary",side?new Vector3(k==0?-2.4f:2.4f,0,0):new Vector3(0,0,k==2?-3.75f:3.75f),side?new Vector3(.12f,.025f,7.5f):new Vector3(4.8f,.025f,.12f),white,null,root);b.markings[k]=line.GetComponent<Renderer>();}b.caption=SportsEventAuthoring.Label("Painted bay phase","CLOSED",root.position+Vector3.up*.045f,.13f,Color.white);b.caption.transform.SetParent(root);b.caption.transform.localPosition=new Vector3(0,.045f,0);b.caption.transform.localRotation=Quaternion.Euler(90,0,0);m.bays[i]=b;}
 m.trucks=new SportsEventTruck[8];m.identities=new TextMesh[8];for(int i=0;i<8;i++){float a=i*Mathf.PI/4;var p=new Vector3(Mathf.Sin(a)*30,.55f,Mathf.Cos(a)*23);m.trucks[i]=SportsEventAuthoring.Truck(m,Folder,"Musical contender "+(i+1),p,i);SportsRallyAuthoring.FitTruck(m.trucks[i]);m.trucks[i].maxSpeed=15;m.trucks[i].steerAngle=36;m.identities[i]=SportsEventAuthoring.Label("Parking identity "+i,m.setup.players[i].name,p+Vector3.up*2.5f,.105f,m.setup.players[i].color);m.identities[i].gameObject.AddComponent<SportsPerCameraBillboard>();}
 m.arenaCamera=SportsEventAuthoring.Camera("Musical Parking shared elevated view");m.arenaCamera.Pose(Vector3.zero,new Vector3(0,68,-42),58,true);m.arenaCamera.view.orthographic=true;m.framing=m.arenaCamera.gameObject.AddComponent<SportsCameraFit>();m.framing.cameraTarget=m.arenaCamera.view;m.framing.arenaFit=true;m.framing.arenaBounds=new Bounds(new Vector3(0,2,0),new Vector3(85,7,69));m.framing.topInset=.045f;m.framing.bottomInset=.06f;m.framing.Apply();m.cameras=new[]{m.arenaCamera.view};m.music=m.gameObject.AddComponent<AudioSource>();m.music.clip=Music();m.music.loop=true;m.music.playOnAwake=false;m.music.spatialBlend=0;Dress(m,contact);SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);m.menus.standings.rectTransform.anchoredPosition=new Vector2(-780,290);m.menus.standings.rectTransform.sizeDelta=new Vector2(310,470);m.menus.standings.fontSizeMax=18;m.menus.standings.fontSizeMin=15;Upgrade(m);SportsEventAuthoring.Save(Folder);Validate();}
 public static void Upgrade(ParkingMatch m){
 foreach(var truck in m.trucks){var c=truck.GetComponent<ParkingRacerContact>();if(c==null)c=truck.gameObject.AddComponent<ParkingRacerContact>();c.match=m;c.slot=truck.slot;}
 var material=SportsEventAuthoring.Mat(Folder,"Legal route yellow paint",new Color(1,.72f,.15f),.12f);
 for(int boundary=0;boundary<2;boundary++){string name=boundary==0?"Legal band inner boundary":"Legal band outer boundary";var found=GameObject.Find(name);var line=found==null?new GameObject(name).AddComponent<LineRenderer>():found.GetComponent<LineRenderer>();line.sharedMaterial=material;line.useWorldSpace=true;line.loop=true;line.widthMultiplier=.16f;line.positionCount=96;line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;line.receiveShadows=false;float radius=boundary==0?ParkingRules.InnerBand:ParkingRules.OuterBand;for(int i=0;i<96;i++){float a=i*Mathf.PI*2/96;line.SetPosition(i,new Vector3(Mathf.Sin(a)*30*radius,.025f,Mathf.Cos(a)*23*radius));}}
 foreach(var bay in m.bays)if(bay.progressFill==null){var fill=SportsEventAuthoring.Box("Physical capture progress paint",Vector3.zero,new Vector3(.001f,.025f,.22f),material,null,bay.transform);bay.progressFill=fill.transform;bay.progressRenderer=fill.GetComponent<Renderer>();fill.SetActive(false);}
 }
 static AudioClip Music(){string path="Assets/"+Folder+"/Audio/Original Parking Polka.wav";if(!File.Exists(path)){const int rate=44100;int samples=rate*16;var random=new System.Random(733);int[] melody={72,76,79,76,74,77,81,77,72,76,79,84,79,76,74,71,72,76,79,76,74,77,81,77,79,77,76,74,72,67,71,72};int[] roots={48,53,48,55};using(var stream=new BinaryWriter(File.Open(path,FileMode.Create))){stream.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));stream.Write(36+samples*2);stream.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));stream.Write(16);stream.Write((short)1);stream.Write((short)1);stream.Write(rate);stream.Write(rate*2);stream.Write((short)2);stream.Write((short)16);stream.Write(System.Text.Encoding.ASCII.GetBytes("data"));stream.Write(samples*2);for(int i=0;i<samples;i++){double time=i/(double)rate,phase=time%.5;int beat=(int)(time/.5);double f=440*Math.Pow(2,(melody[beat%32]-69)/12.0),bass=440*Math.Pow(2,(roots[beat/8]-69)/12.0);double tune=(Math.Sin(time*f*Math.PI*2)+.22*Math.Sin(time*f*Math.PI*4))*Math.Exp(-phase*8)*.24;double low=Math.Sin(time*bass*Math.PI*2)*Math.Exp(-phase*6)*.16;double kick=Math.Sin(phase*(70-30*phase)*Math.PI*2)*Math.Exp(-phase*24)*.16;double hat=(random.NextDouble()*2-1)*Math.Exp(-(time%.25)*75)*.035;stream.Write((short)(Math.Max(-.95,Math.Min(.95,tune+low+kick+hat))*32767));}}AssetDatabase.ImportAsset(path);var importer=(AudioImporter)AssetImporter.GetAtPath(path);importer.forceToMono=true;importer.SaveAndReimport();}return AssetDatabase.LoadAssetAtPath<AudioClip>(path);}
 static void Dress(ParkingMatch m,PhysicsMaterial contact){var root=new GameObject("Installed parking lights signs and barriers").transform;for(int side=-1;side<=1;side+=2){for(int i=0;i<18;i++){var p=new Vector3(-40+i*4.7f,0,side*34);SportsRallyAuthoring.Prop(root,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab",p,new Vector3(4.5f,1.2f,.6f));}for(int i=0;i<14;i++){var p=new Vector3(side*43,0,-31+i*4.8f);var holder=new GameObject("Road barrier").transform;holder.SetParent(root);holder.position=p;holder.rotation=Quaternion.Euler(0,90,0);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock02_URP.prefab",new Vector3(4.5f,1.2f,.6f),0);}var wall=new GameObject("Continuous solid perimeter side").AddComponent<BoxCollider>();wall.transform.SetParent(root);wall.transform.position=new Vector3(side*43,.55f,0);wall.size=new Vector3(.5f,1.1f,69);wall.sharedMaterial=contact;wall=new GameObject("Continuous solid perimeter end").AddComponent<BoxCollider>();wall.transform.SetParent(root);wall.transform.position=new Vector3(0,.55f,side*34);wall.size=new Vector3(86,1.1f,.5f);wall.sharedMaterial=contact;for(int i=0;i<3;i++){var p=new Vector3(-30+i*30,0,side*38);SportsRallyAuthoring.Prop(root,"Assets/Toon Gas Station/Prefabs/Streetlight_1C.prefab",p,new Vector3(4,10,4));var lamp=new GameObject("Parking lamp warm pool").AddComponent<Light>();lamp.transform.SetParent(root);lamp.transform.position=p+Vector3.up*7;lamp.type=LightType.Point;lamp.color=new Color(1,.83f,.5f);lamp.range=18;lamp.intensity=4;lamp.shadows=LightShadows.None;}}for(int i=0;i<25;i++)LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(root,new Vector3(-95+i*8,-.3f,52+i%3*5),7,i%5!=0,Folder);var title=SportsEventAuthoring.Label("Parking entrance sign","MUSICAL PARKING",new Vector3(0,.025f,-31),.18f,new Color(1,.82f,.3f));title.transform.rotation=Quaternion.Euler(90,0,0);}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<ParkingMatch>();if(m==null||m.trucks.Length!=8||m.bays.Length!=8||m.music.clip==null||m.framing==null)throw new Exception("Parking scene references missing");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One parking listener required");Debug.Log("PARKING_SAVED_VALIDATED eight trucks eight rotating bay positions and original looping music");}
}
